// $input.item.json.formatChannel = $('Loop Over Items').item.json.Channel.split(" ").join("-")

// const title = $input.item.json.title

return $input.item;

const page = $json;
const fields = page.properties ?? page;

function readValue(value) {
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) return value.map(readValue).filter(Boolean).join(' ').trim();
  if (!value || typeof value !== 'object') return '';
  if (typeof value.url === 'string') return value.url.trim();
  if (typeof value.plain_text === 'string') return value.plain_text.trim();
  if (typeof value.text === 'string') return value.text.trim();
  if (value.text && typeof value.text.content === 'string') return value.text.content.trim();
  return readValue(value.rich_text ?? value.title ?? value.value);
}

const youtubeUrl = readValue(
  fields['Youtube URL'] ?? fields['YouTube URL'] ?? fields['YouTube Link'] ?? fields['URL'] ?? fields['url']
);
if (!youtubeUrl) throw new Error('Notion page has no YouTube URL. Check the property name and value.');

let parsed;
try { parsed = new URL(youtubeUrl); } catch { throw new Error(`Invalid YouTube URL: ${youtubeUrl}`); }
const host = parsed.hostname.toLowerCase();
if (!['youtube.com', 'www.youtube.com', 'm.youtube.com', 'youtu.be'].includes(host)) {
  throw new Error(`Expected a YouTube video URL, got: ${youtubeUrl}`);
}

return { json: {
  youtubeUrl,
  notionTitle: readValue(fields['Name'] ?? fields['Title']),
  notionPageId: page.id ?? ''
} };

const row = $json;
const captions = row.captions;
if (row.transcriptFound === false || captions == null ||
    (Array.isArray(captions) && captions.length === 0) ||
    (typeof captions === 'string' && !captions.trim())) {
  throw new Error(`No transcript available for video ${row.videoId ?? 'unknown'}: ${row.reason ?? row.status ?? 'captions missing'}`);
}

function timestamp(seconds) {
  const total = Math.max(0, Math.floor(Number(seconds) || 0));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total % 60;
  const mmss = `${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  return hours ? `${hours}:${mmss}` : mmss;
}

const transcript = Array.isArray(captions)
  ? captions.map(segment => typeof segment === 'string'
      ? segment
      : `[${timestamp(segment.start)}] ${segment.text ?? ''}`
    ).filter(Boolean).join('\n')
  : String(captions);

if (!transcript.trim()) throw new Error(`Transcript is empty for video ${row.videoId ?? 'unknown'}`);
return { json: {
  title: row.title || 'Untitled video',
  youtubeUrl: row.videoId ? `https://www.youtube.com/watch?v=${row.videoId}` : '',
  transcript
} };

